{
  "hooks": {
    "PreToolUse": [
      {
        "matcher": "Bash",
        "hooks": [
          {
            "type": "command",
            "command": "jq -r '.tool_input.command' | grep -q 'rm -rf' && exit 2 || true"
          }
        ]
      },
      {
        "hooks": [
          {
            "type": "command",
            "command": "bash \"$CLAUDE_PROJECT_DIR/.claude/skills/t/scripts/jq\" -r '.tool_input.command' | grep -q 'rm -rf' && exit 2 || true"
          }
        ],
        "matcher": "Bash"
      }
    ]
  }
}

